/**
 * Knot vector on [0, 1] from consecutive span lengths: each span has length
 * `distance(start, end) ** alpha` (alpha = 0 uniform, 0.5 centripetal, 1 chordal).
 * If every span has length 0 the knots fall back to uniform spacing instead of NaN.
 */
export function chordKnots(spans: ReadonlyArray<readonly [Point, Point]>, alpha: number): number[] {
    const u = [0];
    for (const [start, end] of spans) {
        u.push(u[u.length - 1] + distance(start, end) ** alpha);
    }
    const total = u[u.length - 1];
    if (!(total > 0)) {
        return u.map((_, i) => i / Math.max(1, spans.length));
    }
    return u.map(t => t / total);

 * points that read it share one computation; never cached while a control point is volatile.
 */
protected getU(): number[] {
    const version = this.version();
    if (version !== VOLATILE && version === this.knotsVersion) {
        return this.knots;
    }
    const knots = chordKnots(this.scheme.knotSpans(this.points, this.bezierCurves), this.alpha);
    if (version !== VOLATILE) {
        this.knots = knots;
        this.knotsVersion = version;
    }
    return knots;

override dispose(): void {
    const auxiliaryObjects = [
        ...this.decasteljauPoints,
        ...this.decasteljauSegments,
        ...this.elevationPoints,
        ...this.elevationSegments,
        this.subdivisionPoint,
        this.extrapolationPoint,
    ].filter((object): object is JXG.Point | JXG.Segment => object !== null);
    if (this.board.renderer && auxiliaryObjects.length > 0) {
        this.board.removeObject(Array.from(new Set(auxiliaryObjects)) as JXG.GeometryElement[]);
    }
    this.decasteljauPoints = [];
    this.decasteljauSegments = [];
    this.elevationPoints = [];
    this.elevationSegments = [];
    this.showingElevatePoints = false;
    this.subdivisionPoint = null;
    this.extrapolationPoint = null;
    this.cachedDecasteljauScheme = [];
    this.cacheRevision = -1;
    this.lastDecasteljauN = -1;
    this.showingDecasteljauScheme = false;
    this.showingDecasteljauPoints = false;
    super.dispose();

export type Language = 'sl' | 'en';
export type MessageKey = keyof typeof sl;
export interface Message {key: MessageKey; params: Record<string, string | number | Message>}
type Parameters<S extends string> = S extends `${string}{${infer P}}${infer Rest}` ? P | Parameters<Rest> : never;
type Args<K extends MessageKey> = [Parameters<typeof sl[K]>] extends [never] ? [] : [Record<Parameters<typeof sl[K]>, string | number>];
type TranslationArguments = {[K in MessageKey]: [key: K, ...args: Args<K>]}[MessageKey];
type MessageArguments = {[K in MessageKey]: [Parameters<typeof sl[K]>] extends [never] ? [key: K] : [key: K, params: Record<Parameters<typeof sl[K]>, string | number | Message>]}[MessageKey];

/** Checks a Preset file without writing: the file envelope, each collection by its definition, and which stored collections it replaces. */
export function preflightPresetImport(contents: string, storage: Storage = window.localStorage): PresetImportPlan {
    let parsed: unknown;
    try { parsed = JSON.parse(contents); } catch { return fail(message("invalid_json")); }
    if (!isRecord(parsed) || Object.keys(parsed).length === 0) return fail(message("missing_preset_collections"));
    for (const [key, stored] of Object.entries(parsed)) {
        const collection = collectionsByStorageKey.get(key) ?? fail(message("unknown_collection", {value0: key}));
        if (!isRecord(stored) || !Array.isArray(stored.data)) fail(message("invalid_collection", {value0: key}));
        const names = new Set<string>();
        for (const preset of stored.data) {
            if (!isRecord(preset) || typeof preset.id !== "string" || !preset.id.trim() || names.has(preset.id)) fail(message("missing_or_duplicate_preset_name"));
            names.add(preset.id);
            checkPreset(collection, preset);
        }
    }
    return {collections: parsed, replacements: Object.keys(parsed).filter(key => storage.getItem(key) !== null)};
